46	
47	/**
48	 * Global Exception handler for REST controllers.
49	 * <p>
50	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
51	 *
52	 * @author Vitaliy Fedoriv
53	 * @author Alexander Dudkin
54	 */
55	@ControllerAdvice
56	public class ExceptionControllerAdvice {
57	
58	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
59	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
60	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
61	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
62	
63	    /**
64	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
65	     * class.
66	     *
67	     * @param e     Object referring to the thrown exception.
68	     * @param status HTTP response status.
69	     * @param url URL request.
70	     */
71	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
72	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
73	        problemDetail.setType(URI.create(url.toString()));
74	        problemDetail.setTitle(e.getClass().getSimpleName());
75	        problemDetail.setDetail(detail);
76	        problemDetail.setProperty("timestamp", Instant.now());
77	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
78	        return problemDetail;
79	    }
80	
81	    /**
82	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
83	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
84	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
85	     * would catch it and report an authorization failure as a 500.
86	     *
87	     * @param e The {@link AccessDeniedException} to propagate
88	     * @throws AccessDeniedException always
89	     */
90	    @ExceptionHandler(AccessDeniedException.class)
91	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
92	        throw e;
93	    }
94	
95	    /**
96	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
97	     *
98	     * @param e The {@link Exception} to be handled
99	     * @param request {@link HttpServletRequest} object referring to the current request.
100	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
101	     */
102	    @ExceptionHandler(Exception.class)
103	    @ResponseBody
104	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
105	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
106	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
107	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
108	        return ResponseEntity.status(status).body(detail);
109	    }
110	
111	    /**
112	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
113	     * method returns a 404 Not Found status if an entity does not exist.
114	     *
115	     * @param e The {@link DataIntegrityViolationException} to be handled
116	     * @param request {@link HttpServletRequest} object referring to the current request.
117	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
118	     */
119	    @ExceptionHandler(DataIntegrityViolationException.class)
120	    @ResponseBody
121	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
122	        logger.warn("Data integrity violation at {} {}: {}",
123	            request.getMethod(),
124	            request.getRequestURI(),
125	            e.getMessage());
126	        logger.debug("Data integrity violation stacktrace", e);
127	        HttpStatus status = HttpStatus.NOT_FOUND;
128	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
129	        return ResponseEntity.status(status).body(detail);
130	    }
131	
132	    /**
133	     * Handles {@link InvalidTelephoneException} raised when an owner's telephone does not contain
134	     * exactly ten digits after non-digit characters are stripped, returning a 400 Bad Request status.
135	     *
136	     * @param e The {@link InvalidTelephoneException} to be handled
137	     * @param request {@link HttpServletRequest} object referring to the current request.
138	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
139	     */
140	    @ExceptionHandler(InvalidTelephoneException.class)
141	    @ResponseBody
142	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
143	        logger.warn("Invalid telephone at {} {}: {}",
144	            request.getMethod(),
145	            request.getRequestURI(),
146	            e.getMessage());
147	        HttpStatus status = HttpStatus.BAD_REQUEST;
148	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
149	        return ResponseEntity.status(status).body(detail);
150	    }
151	
152	    /**
153	     * Handles {@link InvalidEmailException} raised when an owner's e-mail address is present
154	     * but is not a syntactically valid address, returning a 400 Bad Request status.
155	     *
156	     * @param e The {@link InvalidEmailException} to be handled
157	     * @param request {@link HttpServletRequest} object referring to the current request.
158	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
159	     */
160	    @ExceptionHandler(InvalidEmailException.class)
161	    @ResponseBody
162	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
163	        logger.warn("Invalid email at {} {}: {}",
164	            request.getMethod(),
165	            request.getRequestURI(),
166	            e.getMessage());
167	        HttpStatus status = HttpStatus.BAD_REQUEST;
168	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
169	        return ResponseEntity.status(status).body(detail);
170	    }
171	
172	    /**
173	     * Handles {@link InvalidAddressException} raised when an owner's postal address is blank
174	     * once normalized, returning a 400 Bad Request status.
175	     *
176	     * @param e The {@link InvalidAddressException} to be handled
177	     * @param request {@link HttpServletRequest} object referring to the current request.
178	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
179	     */
180	    @ExceptionHandler(InvalidAddressException.class)
181	    @ResponseBody
182	    public ResponseEntity<ProblemDetail> handleInvalidAddressException(InvalidAddressException e, HttpServletRequest request) {
183	        logger.warn("Invalid address at {} {}: {}",
184	            request.getMethod(),
185	            request.getRequestURI(),
186	            e.getMessage());
187	        HttpStatus status = HttpStatus.BAD_REQUEST;
188	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
189	        return ResponseEntity.status(status).body(detail);
190	    }
191	
192	    /**
193	     * Handles {@link InvalidPostcodeException} raised when an owner's supplied postcode is not a
194	     * 4-digit value, or is out of range for the region derived from the owner's city, returning a
195	     * 400 Bad Request status.
196	     *
197	     * @param e The {@link InvalidPostcodeException} to be handled
198	     * @param request {@link HttpServletRequest} object referring to the current request.
199	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
200	     */
201	    @ExceptionHandler(InvalidPostcodeException.class)
202	    @ResponseBody
203	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
204	        logger.warn("Invalid postcode at {} {}: {}",
205	            request.getMethod(),
206	            request.getRequestURI(),
207	            e.getMessage());
208	        HttpStatus status = HttpStatus.BAD_REQUEST;
209	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
210	        return ResponseEntity.status(status).body(detail);
211	    }
212	
213	    /**
214	     * Handles {@link DuplicateIdentityException} raised when an owner is created whose derived
215	     * {@code identityKey} ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId})
216	     * exactly matches that of an existing owner, returning a 409 Conflict status. This single key
217	     * consolidates the former separate telephone, e-mail and household duplicate checks.
218	     *
219	     * @param e The {@link DuplicateIdentityException} to be handled
220	     * @param request {@link HttpServletRequest} object referring to the current request.
221	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
222	     */
223	    @ExceptionHandler(DuplicateIdentityException.class)
224	    @ResponseBody
225	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
226	        logger.warn("Duplicate identity at {} {}: {}",
227	            request.getMethod(),
228	            request.getRequestURI(),
229	            e.getMessage());
230	        HttpStatus status = HttpStatus.CONFLICT;
231	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
232	        return ResponseEntity.status(status).body(detail);
233	    }
234	
235	    /**
236	     * Handles {@link CityCapacityExceededException} raised when an owner is created in a city
237	     * that already contains 50 or more owners, returning a 409 Conflict status.
238	     *
239	     * @param e The {@link CityCapacityExceededException} to be handled
240	     * @param request {@link HttpServletRequest} object referring to the current request.
241	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
242	     */
243	    @ExceptionHandler(CityCapacityExceededException.class)
244	    @ResponseBody
245	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
246	        logger.warn("City at capacity at {} {}: {}",
247	            request.getMethod(),
248	            request.getRequestURI(),
249	            e.getMessage());
250	        HttpStatus status = HttpStatus.CONFLICT;
251	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
252	        return ResponseEntity.status(status).body(detail);
253	    }
254	
255	    /**
256	     * Handles {@link DailyOwnerLimitExceededException} raised when an owner is created after
257	     * 100 or more owners have already been created today (by {@code registrationDate}), returning
258	     * a 429 Too Many Requests status.
259	     *
260	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
261	     * @param request {@link HttpServletRequest} object referring to the current request.
262	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
263	     */
264	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
265	    @ResponseBody
266	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
267	        logger.warn("Daily owner limit reached at {} {}: {}",
268	            request.getMethod(),
269	            request.getRequestURI(),
270	            e.getMessage());
271	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
272	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
273	        return ResponseEntity.status(status).body(detail);
274	    }
275	
276	    /**
277	     * Handles exception thrown by Bean Validation on controller methods parameters
278	     *
279	     * @param e The {@link MethodArgumentNotValidException} to be handled
280	     * @param request {@link HttpServletRequest} object referring to the current request.
281	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
282	     */
283	    @ExceptionHandler(MethodArgumentNotValidException.class)
284	    @ResponseBody
285	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
286	        HttpStatus status = HttpStatus.BAD_REQUEST;
287	        BindingErrorsResponse errors = new BindingErrorsResponse();
288	        BindingResult bindingResult = e.getBindingResult();
289	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
290	        if (bindingResult.hasErrors()) {
291	            errors.addAllErrors(bindingResult);
292	            List<String> errorFields = bindingResult.getFieldErrors().stream()
293	                .map(fieldError -> fieldError.getField())
294	                .distinct()
295	                .toList();
296	            detail.setProperty("errors", errorFields);
297	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
298	                .map(fieldError -> {
299	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
300	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
301	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
302	                        fieldError.getField(),
303	                        defaultMessage,
304	                        rejectedValue);
305	                    return new ValidationMessageDto(message)
306	                        .putAdditionalProperty("field", fieldError.getField())
307	                        .putAdditionalProperty("rejectedValue", rejectedValue)
308	                        .putAdditionalProperty("defaultMessage", defaultMessage);
309	                })
310	                .toList();
311	            logger.debug("Validation error at {} {}: {}",
312	                request.getMethod(),
313	                request.getRequestURI(),
314	                bindingResult.getFieldErrors());
315	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
316	            return ResponseEntity.status(status).body(detail);
317	        }
318	        return ResponseEntity.status(status).body(detail);
319	    }
320	
321	}
